mapper.select:
select STCD,SUM(DRP) DRP,Max(TM) TM from ST_PPTN_R


         and TM >= #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



group by STCD order by DRP desc

select STCD,DATE_FORMAT(TM,'%Y-%m-%d') as TM,SUM(DRP) as DRP from ST_PPTN_R


         and TM >= #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



group by STCD,DATE_FORMAT(TM,'%Y-%m-%d')

select STCD,MAX(DRP) as DRP from (
select STCD,DATE_FORMAT(TM,'%Y-%m-%d %H') as TM,SUM(DRP) as DRP from ST_PPTN_R


         and TM > #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



group by STCD,DATE_FORMAT(TM,'%Y-%m-%d %H')
) as PPTN group by STCD order by DRP desc

select STCD,convert(varchar(19), TM,120) as TM,DRP from ST_PPTN_R


         and TM > #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



and DRP>=0
order by TM asc

select STCD,convert(varchar(19), TM,120) as TM,DRP from ST_PPTN_R


         and TM >= #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



and DRP>=0
order by TM asc

select STCD,convert(varchar(19), TM,120) as TM,DRP from ST_PPTN_R


         and TM >= #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



        wth= #{wth}


order by TM asc

select STCD,convert(varchar(19), TM,120) as TM,DRP from ST_PPTN_R


         and TM > #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}


    and drp > 0

Select c.year,x.STCD,TM,FORMAT(x.z1, 2) as z,case when x.stcd= #{stcd} and sum(x.z) is not null then count(x.stcd)+1 else count(x.stcd) end as orderIndex,ba.stnm
from (select b.ymdhm tm, b.STCD,b.z1, a.Z from (SELECT DATE_FORMAT(ST_RIVER_R.TM, '%m-%d') as ymdhm,
 ST_RIVER_R.TM, ST_RIVER_R.Z as z1,  ST_RIVER_R.STCD FROM ST_RIVER_R


         and ( ST_RIVER_R.STCD in

             #{stcd}

         )


         AND (ST_RIVER_R.TM = DATE_FORMAT(#{etime},'%Y-%m-%d 08:00:00'))


   ) b
  left join (
  SELECT stcd, Z, DATE_FORMAT(tt.TM, '%Y-%m-%d') as ymdhm
 FROM st_river_th tt


         and (tt.STCD in

             #{stcd}

         )

     AND (DATE_FORMAT(tt.TM, '%H:%i:%s') = '08:00:00')

         AND (DATE_FORMAT(tt.TM, '%m-%d') = DATE_FORMAT(#{etime},'%m-%d'))


 ) a  on a.stcd = b.stcd   and a.Z >= b.z1
  order by b.stcd, b.ymdhm desc ) x
 left join
 (
 select stcd,count(DATE_FORMAT(tm,'%Y'))+1 as year from st_river_th


         and stcd in

             #{stcd}


     and DATE_FORMAT(tm,'%m-%d')='01-01'

 group by stcd
 ) c
 on x.STCD=c.stcd
 left join st_stbprp_b ba on x.STCD=ba.stcd
 group by c.year,x.STCD,x.z1,ba.stnm,TM

select STCD,DATE_FORMAT(TM,'%Y-%m-%d %H') as TM,SUM(DRP) as DRP from ST_PPTN_R


         and TM >= #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



group by STCD,DATE_FORMAT(TM,'%Y-%m-%d %H')

select STCD,DATE_FORMAT(DATE_ADD(TM, INTERVAL -5 MINUTE),'%Y-%m-%d %H')  as TM,SUM(DRP) as DRP from ST_PPTN_R


         and TM > #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



        and drp > 0


group by STCD,DATE_FORMAT(DATE_ADD(TM, INTERVAL -5 MINUTE),'%Y-%m-%d %H')  order by DRP desc

select STCD,DATE_FORMAT(DATE_ADD(TM, INTERVAL -485 MINUTE),'%Y-%m-%d') as TM,SUM(DRP) as DRP from ST_PPTN_R


         and TM > #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



        and drp > 0


group by STCD,DATE_FORMAT(DATE_ADD(TM, INTERVAL -485 MINUTE),'%Y-%m-%d') order by DRP desc

select STCD,SUM(DRP) DRP,Max(TM) TM from ST_PPTN_R


         and TM > #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



and DRP>=0
group by STCD
order by DRP desc

select STCD,Max(TM) TM from ST_PPTN_R


         and TM >= #{stime} 


         and TM <= #{etime} 


        and STCD in

            #{stcd}



group by STCD

SELECT STCD, CASE WHEN DATEPART(MINUTE, TM) >= 5 THEN DATEADD(HOUR, 1, DATEADD(HOUR, DATEDIFF(HOUR, 0, TM), 0)) ELSE DATEADD(HOUR, DATEDIFF(HOUR, 0, TM), 0) END AS TM, SUM(DRP) AS DRP FROM ST_PPTN_R
and TM > #{stime}
and TM <= #{etime}
and STCD in
#{stcd}
and DRP>=0 GROUP BY STCD, CASE WHEN DATEPART(MINUTE, TM) >= 5 THEN DATEADD(HOUR, 1, DATEADD(HOUR, DATEDIFF(HOUR, 0, TM), 0)) ELSE DATEADD(HOUR, DATEDIFF(HOUR, 0, TM), 0) END ORDER BY STCD, TM
